# Some generators for random valid tokens from enum set
def random_valid_token(rng: random.Random) -> bytes:
    tok = rng.choice(BRPC_METHODS)
    # random case pattern
    style = rng.randint(0, 3)
    if style == 0:
        s = tok.lower()
    elif style == 1:
        s = tok.upper()
    elif style == 2:
        s = tok.capitalize()
    else:
        s = ''.join(c.lower() if i % 2 else c.upper() for i, c in enumerate(tok))
    return s.encode('ascii')

# Random unknown but plausible token
def random_unknown_token(rng: random.Random) -> bytes:
    # Compose from alphabet with optional dash
    parts = []
    n = rng.randint(3, 16)
    for i in range(n):
        c = rng.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ')
        if rng.random() < 0.12 and i not in (0, n-1):
            parts.append('-')
        parts.append(c)
    tok = ''.join(parts)
    # Ensure it is not one of known methods
    if tok in BRPC_METHODS:
        tok = 'X' + tok
    # Random case
    return random_valid_token(rng) if rng.random() < 0.1 else tok.encode('ascii')

# Main API
def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.random()
    if choice < 0.6:
        # Return a known-good token (higher success rate to exercise enum mapping)
        if rng.random() < 0.5:
            return random_valid_token(rng)
        return rng.choice(CORPUS[: len(CORPUS)//2])
    elif choice < 0.9:
        # Return a mixed-case or extension token from corpus
        return rng.choice(CORPUS)
    else:
        # Occasionally return unknown to test failure path
        return random_unknown_token(rng)

import random
from typing import List

# Note: Keep all byte literals ASCII-only to satisfy validation.

SAFE_ASCII = bytes([c for c in range(32, 127)])

HTTP_METHODS = [
    b"GET", b"POST", b"PUT", b"DELETE", b"HEAD", b"OPTIONS", b"TRACE",
    b"CONNECT", b"PATCH", b"COPY", b"LOCK", b"MKCOL", b"MOVE", b"PROPFIND",
    b"PROPPATCH", b"SEARCH", b"UNLOCK", b"REPORT", b"MKACTIVITY",
    b"CHECKOUT", b"MERGE", b"M-SEARCH", b"NOTIFY", b"SUBSCRIBE",
    b"UNSUBSCRIBE", b"PURGE", b"MKCALENDAR"
]

HTTP_STATUS_LINES = [
    b"HTTP/1.1 200 OK\r\n", b"HTTP/1.1 301 Moved Permanently\r\n",
    b"HTTP/1.1 302 Found\r\n", b"HTTP/1.1 400 Bad Request\r\n",
    b"HTTP/1.1 404 Not Found\r\n", b"HTTP/1.1 500 Internal Server Error\r\n",
]

URL_SCHEMES = [b"http", b"https"]
URL_HOSTS = [
    b"localhost", b"127.0.0.1", b"example.com", b"xn--fsq.com",
    b"api.service.internal", b"[::1]"
]
URL_PATHS = [
    b"/", b"/index.html", b"/api/v1/resource", b"/a/b/c", b"/search",
    b"/utf8/encoded"  # keep ASCII-only literal
]

QUERY_KEYS = [
    b"q", b"id", b"session", b"token", b"page", b"limit", b"sort",
    b"X-Custom", b"a_b", b"CamelCase", b"empty", b"flags"
]

QUERY_VALUES = [
    b"", b"1", b"42", b"true", b"false", b"alpha", b"bravo", b"charlie",
    b"A B", b"a+b", b"email@example.com", b"%2Fpath%2Fto%2Fres",
]

REDIS_INLINE_CMDS = [
    b"PING", b"ECHO hello", b"SET key value", b"GET key", b"INCR counter",
]

def _rand_bytes(rng: random.Random, n_min: int, n_max: int) -> bytes:
    n = rng.randint(n_min, n_max)
    out = bytearray()
    for _ in range(n):
        if rng.random() < 0.85:
            out.append(rng.choice(SAFE_ASCII))
        else:
            out.append(rng.randrange(0, 256))
    return bytes(out)

def _rand_ascii(rng: random.Random, n_min: int, n_max: int) -> bytes:
    n = rng.randint(n_min, n_max)
    return bytes(rng.choices(SAFE_ASCII, k=n))

def _build_url(rng: random.Random) -> bytes:
    scheme = rng.choice(URL_SCHEMES)
    host = rng.choice(URL_HOSTS)
    port = b":" + str(rng.randint(1, 65535)).encode() if rng.random() < 0.5 else b""
    path = rng.choice(URL_PATHS)
    n_q = rng.randint(0, 5)
    kvs = []
    for _ in range(n_q):
        k = rng.choice(QUERY_KEYS)
        v = rng.choice(QUERY_VALUES)
        if rng.random() < 0.3:
            v += b"-" + _rand_ascii(rng, 0, 6)
        kvs.append(k + (b"=" + v if rng.random() < 0.85 else b""))
    query = (b"?" + b"&".join(kvs)) if kvs else b""
    frag = (b"#" + _rand_ascii(rng, 1, 8)) if rng.random() < 0.3 else b""
    if rng.random() < 0.2:
        userinfo = _rand_ascii(rng, 3, 8) + b":" + _rand_ascii(rng, 3, 8) + b"@"
    else:
        userinfo = b""
    return scheme + b"://" + userinfo + host + port + path + query + frag

def _build_query_only(rng: random.Random) -> bytes:
    n = rng.randint(1, 8)
    parts: List[bytes] = []
    for _ in range(n):
        k = rng.choice(QUERY_KEYS)
        if rng.random() < 0.8:
            v = rng.choice(QUERY_VALUES)
            parts.append(k + b"=" + v)
        else:
            parts.append(k)
    return b"&".join(parts)

def _build_http_like_blob(rng: random.Random) -> bytes:
    method = rng.choice(HTTP_METHODS)
    url = _build_url(rng)
    start = method + b" " + url + b" HTTP/1.1\r\n"
    headers = []
    headers.append(b"Host: " + rng.choice(URL_HOSTS) + b"\r\n")
    if rng.random() < 0.6:
        headers.append(b"User-Agent: fuzzgen/1.0\r\n")
    if rng.random() < 0.6:
        headers.append(b"Accept: */*\r\n")
    if rng.random() < 0.4:
        headers.append(b"X-Request-Id: " + _rand_ascii(rng, 6, 24) + b"\r\n")
    hdr = b"".join(headers) + b"\r\n"
    body = b""
    if rng.random() < 0.5:
        body = _rand_bytes(rng, 0, 128)
    return start + hdr + body

def _build_redis_like(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        return rng.choice(REDIS_INLINE_CMDS) + b"\r\n"
    argc = rng.randint(1, 5)
    parts = [b"*" + str(argc).encode() + b"\r\n"]
    for _ in range(argc):
        arg = _rand_ascii(rng, 1, 12)
        parts.append(b"$" + str(len(arg)).encode() + b"\r\n" + arg + b"\r\n")
    return b"".join(parts)

def _build_memcache_like(rng: random.Random) -> bytes:
    key = _rand_ascii(rng, 1, 16)
    val = _rand_ascii(rng, 0, 64)
    exptime = str(rng.randint(0, 3600)).encode()
    flags = str(rng.randint(0, 65535)).encode()
    cmds = []
    cmds.append(b"set " + key + b" " + flags + b" " + exptime + b" " + str(len(val)).encode() + b"\r\n" + val + b"\r\n")
    if rng.random() < 0.7:
        cmds.append(b"get " + key + b"\r\n")
    if rng.random() < 0.5:
        delta = str(rng.randint(1, 1000)).encode()
        cmds.append(b"incr " + key + b" " + delta + b"\r\n")
    return b"".join(cmds)

def _build_webescape_challenger(rng: random.Random) -> bytes:
    parts = [
        b"simple text",
        b" with spaces & symbols !@#",
        b" /utf8/placeholder ",
        b"?q=test&x=1+2%3D3",
        b"\x00\x01\x7f\xff".decode('latin1').encode('latin1')
    ]
    rng.shuffle(parts)
    return b"".join(parts)

def _build_filename_like(rng: random.Random) -> bytes:
    prefixes = [b"/tmp/", b"/var/tmp/", b"C:/temp/", b"./", b"../"]
    name = _rand_ascii(rng, 3, 12)
    ext = rng.choice([b".txt", b".bin", b".dat", b".log"]) if rng.random() < 0.7 else b""
    return rng.choice(prefixes) + name + ext

def _mix_segments(rng: random.Random, budget: int) -> bytes:
    builders = [
        _build_url,
        _build_query_only,
        _build_http_like_blob,
        _build_redis_like,
        _build_memcache_like,
        _build_webescape_challenger,
        _build_filename_like,
        lambda r: _rand_bytes(r, 0, 64),
        lambda r: _rand_ascii(r, 0, 64),
    ]
    buf = bytearray()
    if rng.random() < 0.4:
        buf += rng.choice(HTTP_STATUS_LINES)
    while len(buf) < budget:
        bld = rng.choice(builders)
        seg = bld(rng)
        remain = budget - len(buf)
        if remain <= 0:
            break
        if len(seg) > remain:
            seg = seg[:remain]
        buf += seg
        sep = rng.choice([b"\n", b"\r\n", b"\x00", b"&", b"\n\n"]) if rng.random() < 0.7 else b""
        if len(buf) + len(sep) > budget:
            break
        buf += sep
        if rng.random() < 0.1:
            break
    return bytes(buf)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    target = rng.randint(256, 2048)
    data = _mix_segments(rng, target)
    if not data:
        data = _rand_bytes(rng, 1, 32)
    return data[:4096]
